@param dest: the destination buffer
@param dest_size: the size of the destination buffer
@param src: the source buffer
@param src_size: the size of the source buffer
*/
void copy_to_dest(char* dest, int dest_size, char* src, int src_size) {
    // Ensure dest_size is not zero to avoid issues with dest_size - 1.
    if (dest_size <= 0) {
        return;
    }

    // Determine the number of characters to copy.
    // We want to copy as much as possible from src, but not exceed dest_size.
    // We must leave at least one byte for the null terminator.
    // The number of characters to copy should be the minimum of:
    // 1. The size of the source buffer (src_size)
    // 2. The available space in the destination buffer, which is dest_size - 1 to leave room for null terminator.
    size_t chars_to_copy = (src_size < dest_size - 1) ? src_size : (dest_size - 1);

    // Use strncpy to copy characters.
    // strncpy will copy at most chars_to_copy characters.
    // If src is shorter than chars_to_copy, it will pad with null bytes.
    // If src is longer than or equal to chars_to_copy, it will NOT null-terminate.
    strncpy(dest, src, chars_to_copy);

    // Ensure null termination.
    // If chars_to_copy was equal to dest_size - 1, and src was longer than or equal to dest_size - 1,
    // strncpy would have copied dest_size - 1 characters without null termination.
    // In this case, we must manually null-terminate at the end of the buffer.
    // If src was shorter than dest_size - 1, strncpy would have already null-terminated.
    dest[dest_size - 1] = '\0';
}
